<script>
(function () {
  function escapeHtml(str) {
    return String(str)
      .replace(/&/g, "&amp;")
      .replace(/</g, "&lt;")
      .replace(/>/g, "&gt;");
  }

  // threads.json "date" fields have shown up in a few inconsistent shapes:
  // "Date: 2026-07-01 Time: 0912HRS" (no colon), "Date: ... Time: 20:14HRS" (colon),
  // and "2026-07-08 T13:52". Pull the date out first, then look for a time in
  // whichever shape is present.
  function extractDate(raw) {
    const str = String(raw);
    const dm = str.match(/(\d{4})-(\d{2})-(\d{2})/);
    if (!dm) return new Date(0);
    const y = +dm[1], mo = +dm[2] - 1, da = +dm[3];

    let hh = 0, mm = 0;
    const colonTime = str.match(/(\d{1,2}):(\d{2})/);
    const compactTime = str.match(/Time:\s*(\d{2})(\d{2})\s*HRS/i);
    if (colonTime) {
      hh = +colonTime[1];
      mm = +colonTime[2];
    } else if (compactTime) {
      hh = +compactTime[1];
      mm = +compactTime[2];
    }
    return new Date(y, mo, da, hh, mm);
  }

  function fmtDate(dt) {
    if (isNaN(dt)) return "";
    const dateStr = dt.toLocaleDateString(undefined, { month: "short", day: "numeric", year: "numeric" });
    if (dt.getHours() === 0 && dt.getMinutes() === 0) return dateStr;
    const timeStr = dt.toLocaleTimeString(undefined, { hour: "numeric", minute: "2-digit" });
    return `${dateStr} · ${timeStr}`;
  }

  // Strips markdown/code formatting out of preview text so raw syntax never leaks onto cards
  function previewText(text) {
    const hasCode = /```/.test(text);
    const cleaned = String(text)
      .replace(/```(\w+)?\n[\s\S]*?```/g, "")
      .replace(/<[^>]+>/g, "")
      .replace(/\[(.*?)\]\(.*?\)/g, "$1")
      .replace(/[*_`#>]/g, "")
      .replace(/\s+/g, " ")
      .trim();
    return cleaned + (hasCode ? "  💻" : "");
  }

  fetch("data/threads.json")
    .then((r) => r.json())
    .then((data) => {
      const track = document.getElementById("latest-writing-track");
      const dotsWrap = document.getElementById("latest-writing-dots");
      const threads = data.threads || [];

      // ---- CHANGED: Show threads, not individual entries ----
      // Each slide is a THREAD with only the first 2 entries previewed
      const MAX_THREADS = 8;
      const slides = [];

      threads.forEach((t) => {
        const entries = t.entries || [];
        if (entries.length === 0) return;

        // Get the latest entry date for sorting
        const latestEntry = entries[entries.length - 1];
        const dt = extractDate(latestEntry.date);

        // Get first 2 entries for preview
        const previewEntries = entries.slice(0, 2);

        slides.push({
          threadId: t.id,
          threadTitle: t.title,
          emoji: t.emoji || "🧵",
          tags: t.tags || [],
          entryCount: entries.length,
          latestDate: dt,
          previewEntries: previewEntries,
          firstEntry: entries[0],
          latestEntry: latestEntry
        });
      });

      // Sort by latest entry date (newest first)
      slides.sort((a, b) => b.latestDate - a.latestDate);
      slides.splice(MAX_THREADS);

      if (slides.length === 0) {
        track.innerHTML = '<p class="latest-writing-empty">Nothing posted yet — check back soon.</p>';
        return;
      }

      track.innerHTML = slides
        .map((t) => {
          // Build preview of first 2 entries
          const previewHtml = t.previewEntries.map((e, idx) => {
            const snippet = previewText(e.content);
            const shortSnippet = snippet.length > 100 ? snippet.slice(0, 100) + "…" : snippet;
            return `<div style="font-size:13px;color:#888;margin-top:4px;border-left:2px solid var(--brand-orange);padding-left:10px;margin-bottom:6px;">
              <strong>${idx + 1}.</strong> ${escapeHtml(e.heading)} — ${escapeHtml(shortSnippet)}
            </div>`;
          }).join("");

          const tags = (t.tags || [])
            .slice(0, 3)
            .map((tag) => `<span style="background:var(--bg-cream);color:#886;font-size:10px;font-weight:600;padding:2px 8px;border-radius:12px;margin-right:4px;">${escapeHtml(tag)}</span>`)
            .join("");

          return `
            <a class="latest-post-card" href="thread.html?id=${encodeURIComponent(t.threadId)}">
              <div class="latest-post-thread">${t.emoji} ${escapeHtml(t.threadTitle)}</div>
              <div style="margin-bottom:0.5rem;display:flex;flex-wrap:wrap;gap:0.25rem;">${tags}</div>
              ${previewHtml}
              <div class="latest-post-date" style="margin-top:0.5rem;">🧵 ${t.entryCount} parts · updated ${escapeHtml(fmtDate(t.latestDate))}</div>
            </a>`;
        })
        .join("");

      // ---- Carousel controls ----
      const cards = Array.from(track.children);
      dotsWrap.innerHTML = cards
        .map((_, i) => `<button class="carousel-dot${i === 0 ? " active" : ""}" data-index="${i}" aria-label="Go to slide ${i + 1}"></button>`)
        .join("");
      const dots = Array.from(dotsWrap.children);

      function scrollToCard(i) {
        const card = cards[i];
        if (card) track.scrollTo({ left: card.offsetLeft - track.offsetLeft, behavior: "smooth" });
      }

      dots.forEach((dot, i) => dot.addEventListener("click", () => scrollToCard(i)));

      document.getElementById("latest-prev").addEventListener("click", () => {
        track.scrollBy({ left: -(cards[0].getBoundingClientRect().width + 24), behavior: "smooth" });
      });
      document.getElementById("latest-next").addEventListener("click", () => {
        track.scrollBy({ left: cards[0].getBoundingClientRect().width + 24, behavior: "smooth" });
      });

      let scrollTimeout;
      track.addEventListener("scroll", () => {
        clearTimeout(scrollTimeout);
        scrollTimeout = setTimeout(() => {
          let closest = 0;
          let closestDist = Infinity;
          cards.forEach((card, i) => {
            const dist = Math.abs(card.offsetLeft - track.offsetLeft - track.scrollLeft);
            if (dist < closestDist) {
              closestDist = dist;
              closest = i;
            }
          });
          dots.forEach((d, i) => d.classList.toggle("active", i === closest));
        }, 100);
      });
    })
    .catch(() => {
      document.getElementById("latest-writing-track").innerHTML =
        '<p class="latest-writing-empty">Couldn\'t load latest posts right now.</p>';
    });
})();
</script>
